import base64,json
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2];OLD=P.parent/'pickup-modular-v32'
old=json.loads((OLD/'parts.json').read_text());bank=json.loads((P/'parts.json').read_text());bank['registration']=json.loads((P/'registration.json').read_text())['part_to_original_head_space']
data={'parts':old['parts'],'bank':bank,'source':json.loads((P.parent/'pickup-pilot-v31/source/source.json').read_text()),'images':{}}
for row in old['parts']+bank['parts']:
 file=ROOT/row.get('file',row.get('path'));data['images'][row['name']]='data:image/png;base64,'+base64.b64encode(file.read_bytes()).decode()
html='''<!doctype html><meta charset="utf-8"><title>Hair swap / unchanged motion</title><style>body{font:16px system-ui;background:#192737;color:#edf0fa;margin:24px}canvas{background:#273849;width:384px;height:512px}button,select,input{font:inherit}section{display:flex;gap:12px;flex-wrap:wrap}</style><h1>Hair swap / same eight motion keys</h1><section><div><p>v32 comparison</p><canvas id="baseline" width="384" height="512"></canvas></div><div><p>Replaceable appearance</p><canvas id="view" width="384" height="512"></canvas></div></section><p><select id="style"><option value="silver">Silver</option><option value="auburn">Auburn</option><option value="bald">Base head / no hair</option><option value="original">Original v32</option></select><input id="frame" type="range" min="0" max="7" value="0"><select id="clock"><option value="game">Game timing / 700ms</option><option value="source">Source timing / 1300ms</option></select><button id="play">Play once</button><label><input id="bones" type="checkbox">Rig guide</label></p><p id="status"></p><script>__BASE__</script><script>__HAIR__</script><script>
const DATA=__DATA__,images={},poses=DATA.source.frames.map((_,i)=>ModularPickup.pose(DATA.source,i));let ready=false,index=0,style='silver',running=false,start=0;
function solidHeadMaterial(im){const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height);let changed=0;for(let i=3;i<d.data.length;i+=4)if(d.data[i]>=240&&d.data[i]<255){d.data[i]=255;changed++}x.putImageData(d,0,0);window.headMaterialReceipt={policy:'opaque base-head interior: alpha>=240 becomes255; RGB/sourcefile unchanged, soft outer edges retained',changed_alpha_pixels:changed};return c}
const ctx=document.getElementById('view').getContext('2d'),baseCtx=document.getElementById('baseline').getContext('2d');
Promise.all(Object.entries(DATA.images).map(([n,src])=>new Promise(resolve=>{let im=new Image;im.onload=()=>{images[n]=n==='head.base'?solidHeadMaterial(im):im;resolve()};im.src=src}))).then(()=>{ready=true;draw()});
function rows(i,s){return HairSwap.rows(ModularPickup.recipe(DATA.parts,poses[i]),DATA.bank,s)}
function draw(){if(!ready)return;ModularPickup.render(baseCtx,rows(index,'original'),images,false);ModularPickup.render(ctx,rows(index,style),images,document.getElementById('bones').checked);document.getElementById('frame').value=index;document.getElementById('style').value=style;document.getElementById('status').textContent='Frame '+(index+1)+' / '+style+' / source '+poses[index].source_time_seconds.toFixed(3)+'s'}
document.getElementById('frame').oninput=e=>{running=false;index=+e.target.value;draw()};document.getElementById('style').onchange=e=>{style=e.target.value;draw()};document.getElementById('bones').onchange=draw;
function tick(t){if(!running)return;const elapsed=t-start,game=document.getElementById('clock').value==='game',active=game?700:1300;while(index<7&&(game?(index+1)*100:poses[index+1].source_time_seconds*1000)<=elapsed)index++;draw();if(elapsed>=active+600){running=false;return}requestAnimationFrame(tick)}
document.getElementById('clock').onchange=()=>{running=false;index=0;draw()};document.getElementById('play').onclick=()=>{index=0;running=true;start=performance.now();requestAnimationFrame(tick)};
window.hair={get ready(){return ready},get index(){return index},get running(){return running},get style(){return style},poses,data:DATA,rows,select(s,i=index){style=s;index=i;draw()},frame(i,s,bones=false){ModularPickup.render(ctx,rows(i,s),images,bones);return ctx.canvas.toDataURL('image/png')},headPreview(s){const canvas=document.createElement('canvas');canvas.width=366;canvas.height=365;const c=canvas.getContext('2d'),base=DATA.parts.find(p=>p.name==='head_hair');const rs=HairSwap.rows([{name:'head_hair',part:base,matrix:[1,0,0,1,0,0]}],DATA.bank,s);for(let row of rs){c.save();c.setTransform(...row.matrix);c.drawImage(images[row.name],0,0);c.restore()}return canvas.toDataURL('image/png')}};
</script>'''
html=html.replace('headPreview(s){', "headFrame(i,s){const c=document.createElement('canvas');c.width=384;c.height=512;ModularPickup.render(c.getContext('2d'),rows(i,s).filter(r=>r.name==='head_hair'||r.head_mount_inherited),images,false);return c.toDataURL('image/png')},headPreview(s){")
payload=json.dumps(data,separators=(',',':')).replace('<','\\u003c')
(P/'hair-preview.html').write_text(html.replace('__BASE__',(OLD/'rig-runtime.js').read_text()).replace('__HAIR__',(P/'hair-runtime.js').read_text()).replace('__DATA__',payload))
